#include "ablation/InterfaceMath.H"
#include <fenv.h>
#include <random>
#include <iostream>
#include <iomanip>
using namespace chmt;
int main(){feenableexcept(FE_OVERFLOW|FE_INVALID|FE_DIVBYZERO);std::cout<<std::setprecision(17);std::mt19937_64 rng(1738291);std::uniform_real_distribution<double> u(0,1);int total=0,bad=0;for(int mode=0;mode<6;++mode)for(int c=0;c<1000;++c){PhysicsConfig p;double b[Ns]{},y[Ns]{},j[Ns]{},out[Ns]{},f[Ns]{},sb=0,sy=0,R=0;for(int s=0;s<Ns;++s){b[s]=.01+u(rng);y[s]=.01+u(rng);if(mode<2)y[s]=(s==c%Ns)?1:0;else if(mode<4){if(s%2==0)y[s]=0;}else {if(s%2==0)b[s]=0;}if(Ns==1)y[0]=b[0]=1;sb+=b[s];sy+=y[s];p.species[s].R=10+1000*u(rng);p.gasDiffusivity[s]=1e-6+.01*u(rng);}for(int s=0;s<Ns;++s){b[s]/=sb;y[s]/=sy;R+=p.species[s].R*y[s];out[s]=123;}double rho=101325/(R*300),S=0,J=.01+.1*u(rng);if(mode%2)J=-J;for(int s=0;s<Ns;++s)S+=rho*p.gasDiffusivity[s]/.01*(y[s]-b[s]);for(int s=0;s<Ns;++s)j[s]=J*y[s]+rho*p.gasDiffusivity[s]/.01*(y[s]-b[s])-y[s]*S;double tolerance=1e-12;for(int s=0;s<Ns;++s)tolerance+=p.tolerances.relativeMass*std::abs(j[s]);bool known=compositionResidual(y,b,j,101325,300,.01,p,f,nullptr);double expected=0;for(int s=0;s<Ns;++s)expected=std::max(expected,std::abs(f[s]));if(!known||expected>tolerance)return 3;bool ok=interfaceComposition(j,b,101325,300,.01,p,1e-12,out);double sum=0,norm=0;bool valid=ok&&compositionResidual(out,b,j,101325,300,.01,p,f,nullptr);for(int s=0;s<Ns;++s){sum+=out[s];norm=std::max(norm,std::abs(f[s]));valid=valid&&out[s]>=0&&out[s]<=1;}valid=valid&&std::abs(sum-1)<1e-13&&norm<=tolerance;++total;if(!valid){++bad;if(bad<=4){std::cout<<"BAD mode="<<mode<<" case="<<c<<" ok="<<ok<<" actual="<<norm<<" known="<<expected<<" tol="<<tolerance<<" sum="<<sum<<"\n";for(auto name:{"R","D","bulk","root","Js","out"}){std::cout<<name;for(int s=0;s<Ns;++s)std::cout<<' '<<(std::string(name)=="R"?p.species[s].R:std::string(name)=="D"?p.gasDiffusivity[s]:std::string(name)=="bulk"?b[s]:std::string(name)=="root"?y[s]:std::string(name)=="Js"?j[s]:out[s]);std::cout<<'\n';}}}}std::cout<<"TOTAL "<<total<<" BAD "<<bad<<'\n';return bad?1:0;}